(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8 + Math.cos((y+w1y)*0.028+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.032+t*0.45)*8 + Math.sin((x+w1x)*0.025-t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [60+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.3+1)*50, 0.11, 2.1, 0.6],
    [420+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.65+4)*55, 0.13, 1.8, 1.3]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const tw = 8.4;
  const act=aS/tw, inh=iS/tw, cor=cS/tw;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.07+Math.sin(sy*0.06+t)*2+t*0.3)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2);
  const sp2 = Math.sin(dist*0.08+ang*2-t*2.0)*0.5+Math.sin(dist*0.03-ang*5+t*0.8)*0.4;
  const spiral = (sp1+sp2)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi = (() => {
    let mn = 99, mx = 0;
    for (const [sX,sY] of src) {
      const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
      if(d<mn) mn=d; if(d>mx&&d<200) mx=d;
    }
    return Math.sin(mn*0.15)*Math.cos(mx*0.08-t)*0.3;
  })();
  const laplacian = (() => {
    const eps = 2;
    const v0 = act-inh*0.7+bg*0.3+spiral;
    const vr = Math.sin(Math.sqrt((sx+eps-cx)**2+(sy-cy)**2)*0.05-Math.atan2(sy-cy,sx+eps-cx)*3-t*1.5);
    const vl = Math.sin(Math.sqrt((sx-eps-cx)**2+(sy-cy)**2)*0.05-Math.atan2(sy-cy,sx-eps-cx)*3-t*1.5);
    return (vr+vl-2*sp1*0.5)*0.1;
  })();
  const feed = 0.037+Math.sin(t*0.2)*0.005, kill = 0.06+Math.cos(t*0.15)*0.004;
  const rd = act*act*inh - feed*act - kill*inh + cor*0.3 + laplacian;
  const reaction = Math.tanh((rd + bg*0.3 + spiral + cell + voronoi)*2.0);
  const blend = reaction*0.6 + cell*0.15 + voronoi*0.15 + spiral*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,78,112],[24,118,128],
    [45,155,130],[120,185,110],[195,195,75],
    [220,170,60],[210,130,65],[185,85,72],
    [150,50,68],[100,28,62],[55,18,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.92;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.5)*0.3;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const shimmer = Math.sin(sx*0.3+sy*0.2+t*3)*0.04*Math.abs(reaction);
  return [
    Math.min(255, Math.max(0, (r0*lum*edge+glow*40+shimmer*80))|0),
    Math.min(255, Math.max(0, (g0*lum*edge+glow*30+shimmer*60))|0),
    Math.min(255, Math.max(0, (b0*lum*edge+glow*60+shimmer*40))|0)
  ];
}
